int run() {
  int sum = 0;
  for (int i = 0; i < 10; i++) {
    if (i == 2) { continue; }
    if (i == 5) { break; }
    sum = sum + i;
  }
  int j = 0;
  do {
    sum = sum + 10;
    j++;
  } while (j < 3);
  switch (j) {
    case 3: { sum = sum + 100; break; }
    default: { sum = sum + 1; break; }
  }
  return sum;
}
